// ==============================================================================
// Aggregates offers per user & formats personalized email with test-alias routing
// ==============================================================================
const items = $input.all();
const userOffersMap = new Map();
const testRecipient = $env.SES_TEST_RECIPIENT_EMAIL || 'samarthkolarkar+one@gmail.com';
const senderEmail = $env.SES_FROM_EMAIL || 'noreply@clickpe.com';

for (const item of items) {
  const row = item.json;
  const uid = row.user_id;
  if (!userOffersMap.has(uid)) {
    userOffersMap.set(uid, {
      user_id: uid,
      name: row.name,
      original_email: row.email,
      recipient_email: testRecipient,
      match_ids: [],
      products: []
    });
  }

  const uData = userOffersMap.get(uid);
  uData.match_ids.push(row.match_id);
  uData.products.push({
    product_name: row.product_name,
    provider_name: row.provider_name,
    interest_rate: row.interest_rate,
    max_eligible_loan: row.max_eligible_loan,
    reasoning: row.reasoning
  });
}

const emailPayloads = [];
for (const [uid, data] of userOffersMap.entries()) {
  const productsHtml = data.products.map(p => `
    <div style="border: 1px solid #e2e8f0; border-radius: 8px; padding: 16px; margin-bottom: 12px; background: #ffffff;">
      <h3 style="margin: 0 0 8px 0; color: #1e293b;">${p.product_name} <span style="font-size: 14px; color: #64748b;">by ${p.provider_name}</span></h3>
      <p style="margin: 4px 0; font-size: 15px; color: #0f172a;"><strong>Interest Rate:</strong> <span style="color: #059669; font-weight: bold;">${p.interest_rate}%</span></p>
      <p style="margin: 4px 0; font-size: 15px; color: #0f172a;"><strong>Pre-Approved Borrowing Power:</strong> ₹${Number(p.max_eligible_loan).toLocaleString('en-IN')}</p>
      <p style="margin: 8px 0 0 0; font-size: 13px; color: #475569; font-style: italic;">${p.reasoning}</p>
    </div>
  `).join('');

  const fullHtml = `
    <div style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; max-width: 600px; margin: 0 auto; padding: 24px; background: #f8fafc; border-radius: 12px;">
      <div style="background: #0f172a; padding: 20px; border-radius: 8px; text-align: center; margin-bottom: 24px;">
        <h2 style="color: #ffffff; margin: 0;">ClickPe Loan Eligibility Match</h2>
        <p style="color: #94a3b8; margin: 6px 0 0 0; font-size: 14px;">Personalized Personal Loan Offers</p>
      </div>
      <p style="font-size: 16px; color: #334155;">Hello <strong>${data.name}</strong>,</p>
      <p style="font-size: 15px; color: #475569; line-height: 1.5;">Based on your recent financial profile submission, our automated underwriting engine has matched you with the following pre-qualified loan products:</p>
      ${productsHtml}
      <p style="font-size: 12px; color: #94a3b8; margin-top: 24px; text-align: center;">This is a verified test email sent to <code>${data.recipient_email}</code> on behalf of <code>${data.original_email}</code>.</p>
    </div>
  `;

  emailPayloads.push({
    json: {
      user_id: uid,
      to_email: data.recipient_email,
      subject: `🎉 Exclusive Pre-Approved Loan Matches for ${data.name}`,
      html_body: fullHtml,
      match_ids: data.match_ids
    }
  });
}

return emailPayloads;
